  FT["PH-H6739"] = {"id":"PH-H6739","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8262_1997.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sudipen市","en":"An Act Establishing A Vocational High School in the Municipality of Sudipen, Province of La Union, To Be Known As the Sudipen Vocational High School, and Appropriating Funds Therefor","orig":"An Act Establishing A Vocational High School in the Municipality of Sudipen, Province of La Union, To Be Known As the Sudipen Vocational High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["labor","education"],"docNumber":"Republic Act No. 8262","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-02-16","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8262_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6739-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the direct supervision of the Department of Education, Culture and Sports, a vocational high school in the Municipality of Sudipen, Province of La Union, to be known as the Sudipen Vocational High School."}},{"id":"PH-H6739-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6739-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p96"};
