  FT["PH-H6785"] = {"id":"PH-H6785","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8310_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省卡班卡兰市镇奥林高描笼涯延伸中学从比尼库伊尔中学分离，名称为Florentino Galang，Sr.国立中学，并为此拨款的法案","en":"An Act Providing For the Separation of the Barangay Oringao Extension High School Located in the Municipality of Kabankalan, Province of Negros Occidental, From the Binicuil High School and To Be Known As Florentino Galang, Sr. National High School, and Appropriating Funds Therefor","orig":"An Act Providing For the Separation of the Barangay Oringao Extension High School Located in the Municipality of Kabankalan, Province of Negros Occidental, From the Binicuil High School and To Be Known As Florentino Galang, Sr. National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8310","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8310_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6785-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Barangay Oringao Extension Class located in the Municipality of Kabankalan, Negros Occidental, is hereby separated from the Binicuil High School and shall henceforth be known as the Florentino Galang, Sr. National High School."}},{"id":"PH-H6785-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6785-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Binicuil National High School-Barangay Oringao Extension High School. Thereafter, such sums as may be necessary for the operation and maintenance of the Florentino Galang, Sr. National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6785-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p96","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing For the Separation of the Barangay Oringao Extension High School Located in the Municipality of Kabankalan, Province of Negros Occidental, From the Binicuil High School and To Be Known As Florentino Galang, Sr. National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6786"] = {"id":"PH-H6786","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8311_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将西内格罗斯省Cauayan市镇Inayawan延伸班从Linaon描笼涯中学分离，名称为Eva J. Montilla国立中学，并为此拨款的法案","en":"An Act Providing For the Separation of the Inayawan Extension Class Located in the Municipality of Cauayan, Province of Negros Occidental, From the Linaon Barangay High School, and To Be Known As the Eva J. Montilla National High School, and Appropriating Funds Therefor","orig":"An Act Providing For the Separation of the Inayawan Extension Class Located in the Municipality of Cauayan, Province of Negros Occidental, From the Linaon Barangay High School, and To Be Known As the Eva J. Montilla National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8311","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-14","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8311_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6786-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Inayawan Extension Class located in the Municipality of Cauayan, Negros Occidental, is hereby separated from the Linaon Barangay High School, and shall henceforth be known as the Eva J. Montilla National High School."}},{"id":"PH-H6786-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H6786-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriation of the Linaon National High School–Inayawan Extension Class. Thereafter, such sums as may be necessary for the operation and maintenance of the Eva J. Montilla National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6786-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p96","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing For the Separation of the Inayawan Extension Class Located in the Municipality of Cauayan, Province of Negros Occidental, From the Linaon Barangay High School, and To Be Known As the Eva J. Montilla National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6787"] = {"id":"PH-H6787","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8312_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将阿尔拜省Pioduran市镇Binodegahan描笼涯的Ligao国立中学延伸班从Ligao国立中学分离，改设为独立的国立中学，名称为Pioduran国立中学，并为此拨款的法案","en":"An Act Separating the Ligao National High School Extension Classes Located in Barangay Binodegahan, Municipality of Pioduran, Province of Albay, From the Ligao National High School and Converting the Same Into A Separate and Independent National High School To Be Known As the Pioduran National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Ligao National High School Extension Classes Located in Barangay Binodegahan, Municipality of Pioduran, Province of Albay, From the Ligao National High School and Converting the Same Into A Separate and Independent National High School To Be Known As the Pioduran National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8312","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8312_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6787-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ligao National High School Extension Classes, located in Barangay Binodegahan, Municipality of Pioduran, Province of Albay, is hereby separated from the Ligao National High School and converted into a national high school to be known as the Pioduran National High School."}},{"id":"PH-H6787-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All personnel records, assets, including buildings, sites and improvements thereon, funds and obligations of the Ligao National High School Extension Classes are hereby transferred to the Pioduran National High School."}},{"id":"PH-H6787-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriation of the Ligao National High School - Binodegahan Extension Classes. Thereafter, such sums as may be necessary for the operation and maintenance of the Pioduran National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H6787-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p96","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Ligao National High School Extension Classes Located in Barangay Binodegahan, Municipality of Pioduran, Province of Albay, From the Ligao National High School and Converting the Same Into A Separate and Independent National High School To Be Known As the Pioduran National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6788"] = {"id":"PH-H6788","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8313_1997.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"提升 Quirino 纪念医疗中心、为其拨款并为其他目的法案","en":"An Act Upgrading the Quirino Memorial Medical Center, Appropriating Funds Therefor, and For Other Purposes","orig":"An Act Upgrading the Quirino Memorial Medical Center, Appropriating Funds Therefor, and For Other Purposes"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 8313","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-20","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8313_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6788-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"It is the declared policy of the State to fully protect and safeguard the physical and mental well-being of our citizens."}},{"id":"PH-H6788-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Quirino Memorial Medical Center is hereby formally established and upgraded with a capacity of three hundred fifty (350) hospital beds."}},{"id":"PH-H6788-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The construction and upgrading of the hospital facilities and services shall be under the direct supervision and control of the Department of Health."}},{"id":"PH-H6788-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount of One hundred million pesos (P100,000,000) is hereby authorized to be released from the proceeds of the lotto sponsored by the Philippine Charity Sweepstakes Office for the purchase of equipment."}},{"id":"PH-H6788-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6788-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p96","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Upgrading the Quirino Memorial Medical Center, Appropriating Funds Therefor, and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H6789"] = {"id":"PH-H6789","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8314_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"指定山区省Bauko的Luis Hora纪念医院为科迪勒拉行政大区区域医院并为此拨款的法案","en":"An Act Designating the Luis Hora Memorial Hospital in Bauko, Mountain Province, As the Regional Hospital of the Cordillera Administrative Region, and Appropriating Funds Therefor","orig":"An Act Designating the Luis Hora Memorial Hospital in Bauko, Mountain Province, As the Regional Hospital of the Cordillera Administrative Region, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 8314","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-20","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8314_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6789-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Luis Hora Memorial Hospital in Abatan, Municipality of Bauko, Mountain Province, is hereby designated as the regional hospital of the Cordillera Administrative Region."}},{"id":"PH-H6789-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Upon approval of this Act, all personnel, assets and liabilities of the Luis Hora Memorial Hospital shall be transferred to the Department of Health."}},{"id":"PH-H6789-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6789-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p96","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Designating the Luis Hora Memorial Hospital in Bauko, Mountain Province, As the Regional Hospital of the Cordillera Administrative Region, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
