  FT["PH-H6792"] = {"id":"PH-H6792","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1997/ra_8317_1997.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Lubao市","en":"An Act Establishing A Vocational School in the Municipality of Lubao, Province of Pampanga, To Be Known As the Lubao Vocational School, and Appropriating Funds Therefor","orig":"An Act Establishing A Vocational School in the Municipality of Lubao, Province of Pampanga, To Be Known As the Lubao Vocational School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8317","issuingBody":"Congress of the Philippines","promulgatedDate":"1997-06-30","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1997/ra_8317_1997.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6792-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports (DECS), a vocational school in the Municipality of Lubao, Province of Pampanga, to be known as the Lubao Vocational School."}},{"id":"PH-H6792-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Education, Culture and Sports shall issue such rules and regulations necessary for the effective implementation of this Act."}},{"id":"PH-H6792-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6792-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p96"};
